// FUNCTION: BFME2 0x000634C0 size=33 name=?removeFromScene@W3DGhostObject@@IAEXH@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DGhostObject::removeFromScene(Int playerIndex)
{
	W3DRenderObjectSnapshot *snap = m_parentSnapshots[playerIndex];

	while (snap)
	{
		snap->m_robj->Remove();
		snap = snap->m_next;
	}
}

// FUNCTION: BFME2 0x000634E1 size=39 name=?addToScene@W3DGhostObject@@IAEXH@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DGhostObject::addToScene(Int playerIndex)
{
	W3DRenderObjectSnapshot *snap = m_parentSnapshots[playerIndex];

	while (snap)
	{
		W3DDisplay::m_3DScene->Add_Render_Object(snap->m_robj);
		snap = snap->m_next;
	}
}

// FUNCTION: BFME2 0x00063508 size=15 name=?getShroudStatus@W3DGhostObject@@IAEXH@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DGhostObject::getShroudStatus(Int playerIndex)
{
	// Unlike Zero Hour, a ghost object may have no partition data here.
	if (m_partitionData)
		m_partitionData->getShroudedStatus(playerIndex);
}

