// FUNCTION: BFME2 0x000637B0 size=177 name=?update@W3DRenderObjectSnapshot@@AAEXPAVRenderObjClass@@PAUDrawableInfo@@_N@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DRenderObjectSnapshot::update(RenderObjClass *parent, DrawableInfo *drawInfo, Bool cloneParent)
{
	if (m_robj)
	{
		m_robj->Remove();
		if (m_robj)
		{
			m_robj->Release_Ref();
			m_robj = 0;
		}
	}

	if (cloneParent == true)
	{
		m_robj = parent->Clone();
		m_robj->Set_Transform(parent->Get_Transform());
		if (parent->Class_ID() == RenderObjClass::CLASSID_HLOD)
		{
			float frame, multiplier;
			int mode, numFrames;
			HAnimClass *animation = static_cast<HLodClass *>(parent)->Peek_Animation_And_Info(frame, numFrames, mode, multiplier);
			m_robj->Set_Animation(animation, frame);
			disableUVAnimations(m_robj);
		}
	}
	else
		m_robj = parent;

	m_robj->Set_User_Data(drawInfo);
}

// FUNCTION: BFME2 0x00063861 size=65 name=??0W3DRenderObjectSnapshot@@AAE@PAVRenderObjClass@@PAUDrawableInfo@@_N@Z evidence=N:ledger tier=B hypothesis:cohesion
W3DRenderObjectSnapshot::W3DRenderObjectSnapshot(RenderObjClass *parent, DrawableInfo *drawInfo, Bool cloneParent)
{
	m_robj = 0;
	m_next = 0;
	update(parent, drawInfo, cloneParent);
}

